int parse_imap_fetch_response(struct ImapHeader *h, char *s) {
    char *ptr = s;
    int in_field = 0;
    char field_name[64];
    int field_name_index = 0;
    int in_value = 0;
    char value[256];
    int value_index = 0;

    while (*ptr != '\0') {
        if (*ptr == ' ' || *ptr == '\t') {
            if (in_field && !in_value) {
                in_value = 1;
            }
            ptr++;
            continue;
        }

        if (in_field) {
            if (*ptr == '(') {
                ptr++;
                continue;
            }

            if (*ptr == ')') {
                ptr++;
                break;
            }

            if (in_value) {
                if (*ptr == '{') {
                    ptr++;
                    continue;
                }

                if (*ptr == '}') {
                    ptr++;
                    continue;
                }

                if (strncmp(ptr, "FLAGS", 5) == 0) {
                    ptr += 5;
                    in_field = 0;
                    continue;
                }

                if (strncmp(ptr, "UID", 3) == 0) {
                    ptr += 3;
                    if (sscanf(ptr, "%d", &h->uid) != 1) {
                        return -1;
                    }
                    in_field = 0;
                    continue;
                }

                if (strncmp(ptr, "INTERNALDATE", 12) == 0) {
                    ptr += 12;
                    if (strlen(ptr) < 20) {
                        return -1;
                    }
                    strncpy(h->internaldate, ptr, 20);
                    in_field = 0;
                    continue;
                }

                if (strncmp(ptr, "RFC822.SIZE", 11) == 0) {
                    ptr += 11;
                    if (sscanf(ptr, "%d", &h->size) != 1) {
                        return -1;
                    }
                    in_field = 0;
                    continue;
                }

                if (strncmp(ptr, "BODY", 4) == 0 || strncmp(ptr, "RFC822.HEADER", 13) == 0) {
                    return -2;
                }

                while (*ptr != ' ' && *ptr != '\t' && *ptr != ')' && *ptr != '\0') {
                    ptr++;
                }
                continue;
            } else {
                if (field_name_index < sizeof(field_name) - 1) {
                    field_name[field_name_index++] = *ptr;
                }
                ptr++;
            }
        } else {
            if (*ptr == '(') {
                in_field = 1;
                field_name_index = 0;
                ptr++;
                continue;
            }
            ptr++;
        }
    }

    return 0;
}

